import nltk
from nltk.stem import WordNetLemmatizer
from nltk import pos_tag, word_tokenize
import string

nltk.download('averaged_perceptron_tagger')
nltk.download('punkt')
nltk.download('wordnet')


class Lemmatization:
    PUNCTUATION_TABLE = str.maketrans('', '', string.punctuation)

    def __init__(self):
        self.lemmatizer = WordNetLemmatizer()

    def lemmatize_sentence(self, sentence):
        cleaned_sentence = self.remove_punctuation(sentence)
        words = self._tokenize(cleaned_sentence)
        tagged_words = self._tag_words(words)
        return [self._lemmatize_word(word, tag) for word, tag in tagged_words]

    def get_pos_tag(self, sentence):
        cleaned_sentence = self.remove_punctuation(sentence)
        words = self._tokenize(cleaned_sentence)
        tagged_words = self._tag_words(words)
        return [tag for _, tag in tagged_words]

    def remove_punctuation(self, sentence):
        return sentence.translate(self.PUNCTUATION_TABLE)

    def _tokenize(self, sentence):
        return word_tokenize(sentence)

    def _tag_words(self, words):
        return pos_tag(words)

    def _lemmatize_word(self, word, tag):
        if tag.startswith('V'):
            pos = 'v'
        elif tag.startswith('J'):
            pos = 'a'
        elif tag.startswith('R'):
            pos = 'r'
        else:
            pos = None
        return self.lemmatizer.lemmatize(word, pos=pos) if pos else self.lemmatizer.lemmatize(word)
